export type Pair=readonly [number,number];export type Rect=readonly [number,number,number,number];export type Triple=readonly [number,number,number];
export interface MaterialSpec {id:number;name:string;diffuseFloor:number;diffuseStrength:number;specular:number;shininess:number;shadowStrength:number;highlightBand?:{center:number;width:number;strength:number}}
export interface PaintedShading {strength:number;thresholds:Pair;softness:number;weights:Pair}
import {validateAtmosphere,type SceneAtmosphere,type WindProfile} from './atmosphere.ts';
export interface CharacterPackage {schemaVersion:1;id:string;displayName?:string;canvas:Pair;crop:Rect;fps:number;frameCount:number;atlasSize:Pair;requiredChannels:readonly string[];assetRoot:string;pattern:string;materials:MaterialSpec[];shading?:PaintedShading;wind?:WindProfile;shadow:{maxOffsetPixels:number;softnessPixels:number;ambientOcclusionStrength:number};aeProject:string}
export interface LightKey {minutes:number;name:string;direction:Triple;keyColor:Triple;ambient:Triple;lampDirection:Triple;lampColor:Triple;exposure:number;backgroundTint:Triple;backgroundExposure:number}
export interface SceneControls {initialMinutes:number;previewMinutesPerSecond:number;presets:readonly {name:string;minutes:number}[]}
import {validateEnvironment,type SceneEnvironment} from './scene-environment.ts';
import {validateTimeBackground,type TimeBackground} from './time-background.ts';
export interface ScenePackage {schemaVersion:1;id:string;canvas:Pair;background:{path:string;rect:Rect;timeOfDay?:TimeBackground};controls:SceneControls;keyframes:LightKey[];environment?:SceneEnvironment;atmosphere?:SceneAtmosphere}
export interface WallpaperPackage {schemaVersion:1;id:string;displayName?:string;characterId:string;sceneId:string;canvas:Pair;preview:Rect;characterOrigin:Pair;drawOrder:readonly string[];scope:string;presentation?:{selectable:boolean;characterKey:string;sceneName:string;focus:Pair;thumbnail?:string}}
function object(v:unknown,label:string):Record<string,any>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error(label+' must be an object');return v as Record<string,any>}
function numbers(v:unknown,length:number,label:string,positive=false){if(!Array.isArray(v)||v.length!==length||v.some(x=>!Number.isFinite(x)||(positive&&x<=0)))throw Error(label+' must have '+length+' finite values');return v as number[]}
function schema(v:Record<string,any>,label:string){if(v.schemaVersion!==1)throw Error(label+' schemaVersion unsupported: '+v.schemaVersion);if(typeof v.id!=='string'||!v.id)throw Error(label+' id missing')}
function scalar(v:unknown,label:string,min=0,max=Infinity,exclusiveMin=false){if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||(exclusiveMin&&v===min))throw Error(label+' is outside its finite range')}
function text(v:unknown,label:string){if(typeof v!=='string'||!v.trim())throw Error(label+' missing')}
function rect(v:unknown,canvas:number[],label:string){const r=numbers(v,4,label);if(r[0]<0||r[1]<0||r[2]<=0||r[3]<=0||r[0]+r[2]>canvas[0]||r[1]+r[3]>canvas[1])throw Error(label+' outside canvas')}
export function validateCombination(character:unknown,scene:unknown,wallpaper:unknown){
  const c=object(character,'character'),s=object(scene,'scene'),p=object(wallpaper,'wallpaper');schema(c,'character');schema(s,'scene');schema(p,'wallpaper');
  numbers(p.canvas,2,'wallpaper canvas',true);
  for(const [label,v] of [['character',c],['scene',s]] as const){numbers(v.canvas,2,label+' canvas',true);if(v.canvas.some((n:number,i:number)=>n!==p.canvas[i]))throw Error(label+' canvas mismatch')}
  if(p.characterId!==c.id||p.sceneId!==s.id)throw Error('wallpaper package ids mismatch');
  for(const [label,rect] of [['character crop',c.crop],['wallpaper preview',p.preview]] as const){numbers(rect,4,label);if(rect[0]<0||rect[1]<0||rect[2]<=0||rect[3]<=0||rect[0]+rect[2]>p.canvas[0]||rect[1]+rect[3]>p.canvas[1])throw Error(label+' outside canvas')}
  numbers(p.characterOrigin,2,'wallpaper characterOrigin');
  if(p.presentation!==undefined){const view=object(p.presentation,'wallpaper presentation');text(view.characterKey,'presentation characterKey');text(view.sceneName,'presentation sceneName');const focus=numbers(view.focus,2,'presentation focus');if(focus.some(v=>v<0||v>1)||typeof view.selectable!=='boolean')throw Error('wallpaper presentation invalid')}
  if(p.characterOrigin[0]<0||p.characterOrigin[1]<0||p.characterOrigin[0]+c.crop[2]>p.canvas[0]||p.characterOrigin[1]+c.crop[3]>p.canvas[1])throw Error('wallpaper characterOrigin outside canvas');
  if(!Number.isFinite(c.fps)||c.fps<=0||!Number.isSafeInteger(c.frameCount)||c.frameCount<=0)throw Error('character timing invalid');
  numbers(c.atlasSize,2,'character atlasSize',true);if(c.atlasSize[0]!==c.crop[2]*2||c.atlasSize[1]!==c.crop[3]*2)throw Error('character atlasSize mismatch');
  const required=['albedo','normal','material','shadow'];if(!Array.isArray(c.requiredChannels)||c.requiredChannels.length!==required.length||!required.every(k=>c.requiredChannels.includes(k)))throw Error('character requiredChannels mismatch');
  if(typeof c.assetRoot!=='string'||typeof c.pattern!=='string'||!c.pattern.includes('{frame:04}'))throw Error('character asset path missing');
  if(!Array.isArray(c.materials)||!c.materials.length||c.materials.some((m:any)=>!Number.isInteger(m.id)||m.id<1||m.id>=16)||new Set(c.materials.map((m:any)=>m.id)).size!==c.materials.length)throw Error('character material ids invalid');
  for(const m of c.materials){text(m.name,'material name');for(const k of ['diffuseFloor','diffuseStrength','specular'])scalar(m[k],'material '+k);scalar(m.shininess,'material shininess',0,Infinity,true);scalar(m.shadowStrength,'material shadowStrength',0,1);if(m.highlightBand!==undefined){const band=object(m.highlightBand,'material highlightBand');scalar(band.center,'highlightBand center',0,1);scalar(band.width,'highlightBand width',0,1,true);scalar(band.strength,'highlightBand strength')}}
  if(c.shading!==undefined){const style=object(c.shading,'character shading');scalar(style.strength,'shading strength',0,1);scalar(style.softness,'shading softness',0,1,true);const thresholds=numbers(style.thresholds,2,'shading thresholds');if(thresholds[0]<-1||thresholds[1]>1||thresholds[0]>=thresholds[1])throw Error('shading thresholds must increase within [-1,1]');const weights=numbers(style.weights,2,'shading weights');if(weights.some(v=>v<0)||Math.abs(weights[0]+weights[1]-1)>1e-6)throw Error('shading weights must be nonnegative and sum to 1')}
  if(c.wind!==undefined){const wind=object(c.wind,'character wind');scalar(wind.primaryCycles,'wind primary cycles',1,16);scalar(wind.secondaryCycles,'wind secondary cycles',1,16);scalar(wind.secondaryPhase,'wind secondary phase',-100,100);scalar(wind.secondaryStrength,'wind secondary strength',0,1);if(!Number.isInteger(wind.primaryCycles)||!Number.isInteger(wind.secondaryCycles))throw Error('wind cycles must be integer for loop continuity')}
  const shadow=object(c.shadow,'character shadow');scalar(shadow.maxOffsetPixels,'shadow maxOffsetPixels');scalar(shadow.softnessPixels,'shadow softnessPixels');scalar(shadow.ambientOcclusionStrength,'shadow ambientOcclusionStrength',0,1);
  const background=object(s.background,'scene background');text(background.path,'scene background path');rect(background.rect,p.canvas,'scene background rect');
  if(background.timeOfDay!==undefined)validateTimeBackground(background.timeOfDay);
  const controls=object(s.controls,'scene controls');scalar(controls.initialMinutes,'scene initialMinutes',0,1439);scalar(controls.previewMinutesPerSecond,'scene previewMinutesPerSecond',0,Infinity,true);
  if(!Array.isArray(controls.presets)||!controls.presets.length)throw Error('scene presets missing');
  for(const preset of controls.presets){text(preset?.name,'scene preset name');scalar(preset?.minutes,'scene preset minutes',0,1439)}
  if(!Array.isArray(s.keyframes)||s.keyframes.length<2||s.keyframes[0].minutes!==0||s.keyframes.at(-1).minutes!==1440||s.keyframes.some((k:any,i:number)=>!Number.isFinite(k.minutes)||(i&&k.minutes<=s.keyframes[i-1].minutes)))throw Error('scene keyframes must span one day in order');
  for(const key of s.keyframes){text(key.name,'scene light name');for(const field of ['direction','lampDirection']){const vector=numbers(key[field],3,'scene '+field);if(Math.hypot(...vector)<1e-6)throw Error('scene '+field+' cannot be zero')}for(const field of ['keyColor','ambient','lampColor','backgroundTint']){const vector=numbers(key[field],3,'scene '+field);if(vector.some(n=>n<0))throw Error('scene '+field+' cannot be negative')}scalar(key.exposure,'scene exposure',0,Infinity,true);scalar(key.backgroundExposure,'scene backgroundExposure',0,Infinity,true)}
  if(!Array.isArray(p.drawOrder)||p.drawOrder.length!==2||new Set(p.drawOrder).size!==2||!['scene','character'].every(name=>p.drawOrder.includes(name)))throw Error('wallpaper drawOrder must explicitly contain scene and character');
  if(s.environment!==undefined){validateEnvironment(s.environment,p.canvas as unknown as Pair);if(s.background.rect.some((v:number,i:number)=>v!==[0,0,...p.canvas][i]))throw Error('dynamic environment background must cover its canvas')}
  if(s.atmosphere!==undefined){validateAtmosphere(s.atmosphere,p.canvas as unknown as Pair);if(!s.environment)throw Error('atmosphere requires scene environment masks');if(!c.wind)throw Error('atmosphere requires a character wind profile')}
  return {character:c as CharacterPackage,scene:s as ScenePackage,wallpaper:p as WallpaperPackage};
}
